import {state,esc,dateKey,uid} from '../../lib/store.js';
import {news} from '../../data/seed.js';
import {literature} from '../../data/legacy-literature.js';
import {panel,button as baseButton,area,input,empty} from '../pixel/primitives.js';
import {selectedArticle,ensureExcerpt} from './live-news.js';
import {words,safeLink} from '../../lib/training-text.js';
const button=(text,action,extra='',cls='')=>baseButton(text,action,'type="button" '+extra,cls);
export const chatLink='<a class="button" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">OPEN CHATGPT ↗</a>';
export function currentRecord(mode='PT-ZH'){const a=selectedArticle(),e=ensureExcerpt();return mode==='ZH-PT'?{mode,articleTitle:'手动中文材料',source:'MANUAL',category:'Manual',articleUrl:'',publishedAt:'',originalExcerpt:state.drafts['manual-zh-source']||'',userTranslation:state.drafts['manual-zh-translation']||''}:{mode,articleTitle:a?.title||'',source:a?.source||'',category:a?.category||'',articleUrl:a?.url||'',publishedAt:a?.publishedAt||'',originalExcerpt:e?.excerpt||'',userTranslation:state.drafts[e?.draftKey]||''}}
export function makeRecord(mode,text){const r=currentRecord(mode);if(!r.originalExcerpt.trim())throw Error('请先选择有可用文本的新闻，或输入中文原文。');if(!text.trim())throw Error('请先填写译文。');return {...r,id:uid(),date:dateKey(),completedAt:new Date().toISOString(),userTranslation:text}}
export function historyRecords(){return state.translations.map(t=>{if(t.completedAt)return t;const old=news.find(a=>a.id===t.source),lit=t.source==='literature';return {id:t.id,date:dateKey(t.time),completedAt:new Date(t.time).toISOString(),mode:t.mode,articleTitle:lit?literature.title:old?.title||'旧版练习',source:lit?literature.author:'旧版示例练习',articleUrl:lit?literature.source:'',category:lit?'Literature':old?.category||'Legacy',publishedAt:'',originalExcerpt:lit?literature.excerpt:old?(t.mode==='ZH-PT'?old.zh:old.body):'旧记录未保存原文。',userTranslation:t.text||''}}).sort((a,b)=>b.completedAt.localeCompare(a.completedAt))}
export function translationView(ui){const mode=ui.translationMode,a=selectedArticle(),e=ensureExcerpt(),manual=mode==='ZH-PT';return panel('TRANSLATION PROTOCOL',`<div class="actions">${button('PT → ZH','translation-mode','data-value="PT-ZH"',!manual?'primary':'')}${button('ZH → PT','translation-mode','data-value="ZH-PT"',manual?'primary':'')}${button('TRANSLATION HISTORY','tab','data-key="training" data-value="history"')}</div>${manual?'<p class="notice">自行粘贴中文材料；网站不会自动翻译新闻。</p>':a?`<dl class="translation-meta"><dt>SOURCE</dt><dd>${esc(a.source)}</dd><dt>ARTICLE</dt><dd>${esc(a.title)}</dd><dt>DATE / CATEGORY</dt><dd>${esc(new Date(a.publishedAt).toLocaleString())} / ${esc(a.category)}</dd></dl><p class="micro">SOURCE TEXT: ${esc(a.textKind||'RSS SUMMARY')} · ${words(e.excerpt)} WORDS · ${e.count} EXCERPT(S)</p>${words(e.excerpt)<40?'<p class="notice">RSS 摘要不足 40 词，仅使用媒体实际提供的短文本。READ 可前往原站阅读。</p>':''}`:empty('请先在新闻中点击 USE FOR TRAINING。')}<form data-form="translation" data-mode="${mode}">${manual?area('original','ORIGINAL / 中文原文',state.drafts['manual-zh-source']||'','data-draft="manual-zh-source" required'):a?`<div class="reading-text" lang="pt">${esc(e.excerpt)}</div>`:''}${manual||a?`${area('text','YOUR TRANSLATION / 草稿自动保存',state.drafts[manual?'manual-zh-translation':e.draftKey]||'',`data-draft="${manual?'manual-zh-translation':e.draftKey}" required`)}<div class="actions"><button class="button primary">SAVE TRANSLATION</button>${!manual?button('NEW EXCERPT','excerpt-new'):''}${button('COPY FOR CHATGPT','translation-copy')}${chatLink}</div>`:''}</form><p class="micro muted">只复制，不自动发送。打开 ChatGPT 后由你手动粘贴。本站不调用 AI，也不提供自动评分。</p>`)}
export function historyView(ui){const all=historyRecords(),f=ui.translationFilters||{},week=new Date();week.setHours(0,0,0,0);week.setDate(week.getDate()-(week.getDay()+6)%7);const records=all.filter(r=>(!f.date||r.date===f.date)&&(!f.source||r.source===f.source)&&(!f.category||r.category===f.category)&&(!f.mode||r.mode===f.mode)&&(!f.q||[r.articleTitle,r.originalExcerpt,r.userTranslation].join(' ').toLowerCase().includes(f.q.toLowerCase())));const select=(name,label,values)=>`<label class="field"><span>${label}</span><select name="${name}"><option value="">ALL</option>${values.map(v=>`<option ${f[name]===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;return panel('TRANSLATION HISTORY',`<p class="eyebrow">TODAY ${all.filter(r=>r.date===dateKey()).length} / THIS WEEK ${all.filter(r=>new Date(r.completedAt)>=week).length} / TOTAL ${all.length}</p><form data-form="translation-search" class="history-filters">${input('q','搜索标题 / 原文 / 译文',f.q||'')}${input('date','日期',f.date||'','date')}${select('source','来源',[...new Set(all.map(r=>r.source))])}${select('category','分类',[...new Set(all.map(r=>r.category))])}${select('mode','方向',['PT-ZH','ZH-PT'])}<button class="button">FILTER</button>${button('CLEAR','history-clear')}</form><div class="translation-records">${records.map(r=>`<button class="news-card" data-action="translation-detail" data-id="${esc(r.id)}"><span class="micro muted">${esc(new Date(r.completedAt).toLocaleString())} · ${esc(r.source)} · ${esc(r.mode)}</span><h3>${esc(r.articleTitle)}</h3><p>${esc(r.originalExcerpt.slice(0,150))}</p><p class="cyan">${esc(r.userTranslation.slice(0,120))}</p></button>`).join('')||empty('尚无符合条件的记录。每次保存都会保留独立版本。')}</div>`)}
export function historyDetail(id){const r=historyRecords().find(r=>r.id===id);if(!r)return empty('记录不存在');return `<h3>${esc(r.articleTitle)}</h3><p class="muted">${esc(r.source)} · ${esc(r.category)} · ${esc(r.mode)}<br>${esc(new Date(r.completedAt).toLocaleString())}</p><h3>ORIGINAL</h3><div class="reading-text">${esc(r.originalExcerpt)}</div><h3>MY TRANSLATION</h3><div class="reading-text">${esc(r.userTranslation)}</div><div class="actions">${button('COPY FOR CHATGPT','translation-copy',`data-id="${esc(r.id)}"`)}${chatLink}${safeLink(r.articleUrl)?`<a class="button" href="${esc(safeLink(r.articleUrl))}" target="_blank" rel="noopener noreferrer">OPEN ORIGINAL ARTICLE ↗</a>`:''}${button('DELETE','translation-delete',`data-id="${esc(r.id)}"`,'danger')}</div>`}
